// Kalkulator JavaScript Sederhana

function tambah(a, b) {
  return a + b;
}

function kurang(a, b) {
  return a - b;
}

function kali(a, b) {
  return a * b;
}

function bagi(a, b) {
  if (b === 0) {
    return "Error: Tidak bisa bagi dengan 0!";
  }
  return a / b;
}

// Test kalkulator
console.log("10 + 5 =", tambah(10, 5));
console.log("10 - 5 =", kurang(10, 5));
console.log("10 × 5 =", kali(10, 5));
console.log("10 ÷ 5 =", bagi(10, 5));
console.log("10 ÷ 0 =", bagi(10, 0));

